 for(let i=0;i<4;i++){const status=Number(out[i]?.statusCode||0);if(status<200||status>=300)throw new Error('WIKI_INDEXES_UNAVAILABLE');}
 const r=planned[0],bodies=Object.fromEntries(planned.map((p,i)=>[p.resource_path,httpBody(out[i])])),manifest=parseManifest(bodies['manifest.json']);
 const registered=manifest.documents.some(d=>d.path===r.path||(/^\d+$/.test(r.job_id)&&d.path.startsWith('wiki/records/'+r.job_id+'-')));
 if(!registered)for(let i=4;i<planned.length;i++){const status=Number(out[i]?.statusCode||0);if(planned[i].new_resource){if(status!==404)throw new Error(status>=200&&status<300?'WIKI_NEW_RESOURCE_EXISTS':'WIKI_NEW_RESOURCE_UNAVAILABLE');}else if(status<200||status>=300)throw new Error('WIKI_PATCH_DOCUMENT_UNAVAILABLE');}
 const plan=prepareWikiCommit(r,manifest,bodies['index.md'],bodies['log.md'],JSON.parse(bodies['graph.json']),r.base_tree,bodies);return [{json:{...plan,parent_sha:r.parent_sha,sha:r.parent_sha,job_id:r.job_id}}];
